import{a as p}from"./chunks/theme.CMKb-o9K.js";import{_ as u,o as r,c as n,a2 as d,C as i,j as t,a as o,G as a}from"./chunks/framework.BgSoyxN5.js";const g={},b={class:"diagnostics-guide","aria-labelledby":"diagnostics-guide-title"};function v(l,s){return r(),n("section",b,s[0]||(s[0]=[d('<header class="diagnostics-guide__header" data-v-eb267400><span data-v-eb267400>Read the reports</span><h2 id="diagnostics-guide-title" data-v-eb267400>What Your Portfolio Diagnostics Mean</h2><p data-v-eb267400> Start with the Snapshot, then use the deeper reports to understand why a number is high or low. Each result describes portfolio structure, not a prediction or a personalized buy or sell instruction. </p></header><article class="diagnostics-guide__report" data-v-eb267400><div class="diagnostics-guide__reportTitle" data-v-eb267400><span data-v-eb267400>01</span><div data-v-eb267400><h3 data-v-eb267400>Portfolio Snapshot</h3><p data-v-eb267400>A one-screen summary of quality, exposure, concentration, and downside sensitivity.</p></div></div><div class="diagnostics-guide__terms" data-v-eb267400><section id="snapshot-scores" data-v-eb267400><h4 data-v-eb267400>Scores</h4><p data-v-eb267400><strong data-v-eb267400>Overall</strong> combines the portfolio&#39;s weighted TickerForge and Piotroski results after structural caps. Higher is healthier: <b data-v-eb267400>80-100 strong</b>, <b data-v-eb267400>60-79 needs review</b>, and <b data-v-eb267400>below 60 fragile</b>. </p><p data-v-eb267400><strong data-v-eb267400>TickerForge Score</strong> summarizes business and valuation quality. <strong data-v-eb267400>Piotroski</strong> emphasizes accounting strength. Read the <a href="/methodology/tickerforge-score" data-v-eb267400>TickerForge Score methodology</a>. </p></section><section id="snapshot-exposure" data-v-eb267400><h4 data-v-eb267400>Exposure</h4><p data-v-eb267400> Net liquidity is cash plus signed position value. Gross exposure counts the absolute size of every position. Example: $10K equity with $15K gross exposure is leveraged; a large cash percentage reduces market sensitivity. </p></section><section id="snapshot-concentration" data-v-eb267400><h4 data-v-eb267400>Concentration</h4><p data-v-eb267400> Top Position and Top Sector reveal single points of failure. As practical review levels, inspect a stock above <b data-v-eb267400>25%</b> or a sector above <b data-v-eb267400>30%</b>. These are warning thresholds, not automatic sell rules. </p></section><section id="snapshot-stress-scenario" data-v-eb267400><h4 data-v-eb267400>Stress Scenario</h4><p data-v-eb267400> Expected Drawdown estimates the portfolio response to the selected S&amp;P 500 shock. A -10% market shock producing -20% portfolio drawdown indicates roughly twice the downside sensitivity of the benchmark. </p></section><section id="snapshot-diagnostics" data-v-eb267400><h4 data-v-eb267400>Diagnostics</h4><p data-v-eb267400> Risk Profile summarizes the strongest structural warning. &quot;Financial distress risk detected&quot; means at least one holding has an elevated balance-sheet distress signal; it does not mean bankruptcy is certain. </p></section></div></article><article class="diagnostics-guide__report" data-v-eb267400><div class="diagnostics-guide__reportTitle" data-v-eb267400><span data-v-eb267400>02</span><div data-v-eb267400><h3 data-v-eb267400>Portfolio Health Check</h3><p data-v-eb267400> A deduction-based audit of diversification, business quality, risk, cash, and leverage. <a href="/methodology/portfolio-health-check" data-v-eb267400>See the complete methodology</a>. </p></div></div><div class="diagnostics-guide__terms" data-v-eb267400><section id="health-scores" data-v-eb267400><h4 data-v-eb267400>Health Scores</h4><p data-v-eb267400> The Health Score begins at 100 and loses points for structural weaknesses. Risk Level is derived from position and sector concentration, high-risk holdings, and the weighted Fundamental Risk Score. </p></section><section id="health-exposure" data-v-eb267400><h4 data-v-eb267400>Exposure</h4><p data-v-eb267400> Compare net liquidation with gross exposure. Gross exposure above net liquidation signals leverage. Cash can cushion shocks, although very high cash may reduce capital efficiency. </p></section><section id="health-concentration" data-v-eb267400><h4 data-v-eb267400>Concentration</h4><p data-v-eb267400> Max Position and Max Sector show where portfolio outcomes depend on one company or one economic theme. More tickers do not help if they all belong to the same sector. </p></section><section id="health-quality-lens" data-v-eb267400><h4 data-v-eb267400>Quality Lens</h4><p data-v-eb267400> Average TickerForge and Piotroski values are position-weighted. A large weak holding therefore matters more than a tiny weak holding. </p></section><section id="health-diagnostics" data-v-eb267400><h4 data-v-eb267400>Risk Metrics &amp; Diagnostics</h4><p data-v-eb267400> Market Risk (Beta) estimates price sensitivity: near 1.0 resembles the market, below 1.0 is usually calmer, and above 1.3 is more aggressive. Fundamental Risk Score runs in the opposite direction: <b data-v-eb267400>lower is better</b>; below 35 is generally lower risk, 35-49 needs review, and 50+ is elevated. <a href="/methodology/risk-score" data-v-eb267400>See the Risk Score methodology</a>. </p></section></div></article><article class="diagnostics-guide__report" data-v-eb267400><div class="diagnostics-guide__reportTitle" data-v-eb267400><span data-v-eb267400>03</span><div data-v-eb267400><h3 data-v-eb267400>Sector Allocation</h3><p data-v-eb267400>Shows whether diversification exists across economic drivers, with cash kept visible.</p></div></div><div class="diagnostics-guide__terms" data-v-eb267400><section id="sector-exposure" data-v-eb267400><h4 data-v-eb267400>Exposure</h4><p data-v-eb267400> Cash appears separately from invested sectors. This prevents a portfolio with a large reserve from being presented as 100% invested. </p></section><section id="sector-concentration" data-v-eb267400><h4 data-v-eb267400>Sector Concentration</h4><p data-v-eb267400> A top sector above 30% deserves review. Cyclical Tilt measures exposure to areas that usually react more strongly to economic expansion and contraction: below 40% is lower, 40-54% moderate, and 55%+ high. </p></section><section id="sector-allocation" data-v-eb267400><h4 data-v-eb267400>Allocation Chart</h4><p data-v-eb267400> Use the chart to find hidden clusters. For example, software, semiconductors, and internet stocks may look different by ticker but still create one Technology bet. </p></section></div></article><article class="diagnostics-guide__report" data-v-eb267400><div class="diagnostics-guide__reportTitle" data-v-eb267400><span data-v-eb267400>04</span><div data-v-eb267400><h3 data-v-eb267400>Stress Test</h3><p data-v-eb267400> A beta-based scenario, not a forecast. <a href="/methodology/portfolio-stress-test" data-v-eb267400>See the formulas and limitations</a>. </p></div></div><div class="diagnostics-guide__terms" data-v-eb267400><section id="stress-scenario" data-v-eb267400><h4 data-v-eb267400>Scenario</h4><p data-v-eb267400> The engine applies the selected S&amp;P 500 move to every position using its beta, direction, and size. Cash does not move. Test both falling and rising markets, especially when the portfolio contains short positions. </p></section><section id="stress-impact" data-v-eb267400><h4 data-v-eb267400>Impact Summary</h4><p data-v-eb267400> Net Impact combines estimated long losses and short hedge effects. Margin Utilization and Required Equity matter mainly for leveraged books; a deficit is a warning that the simulated move may breach the model&#39;s maintenance assumption. </p></section><section id="stress-position-impacts" data-v-eb267400><h4 data-v-eb267400>Top Position Impacts</h4><p data-v-eb267400> These are the holdings contributing most to the simulated gain or loss. They are the first positions to review when one scenario dominates the whole portfolio. </p></section></div></article>',5)]))}const f=u(g,[["render",v],["__scopeId","data-v-eb267400"]]),w=JSON.parse('{"title":"Import Portfolio: Free Portfolio Health Check and Stress Test | TickerForge","description":"Add stock holdings and cash in USD, then run portfolio diagnostics: health check, concentration review, sector allocation, and stress test.","frontmatter":{"title":"Import Portfolio: Free Portfolio Health Check and Stress Test | TickerForge","description":"Add stock holdings and cash in USD, then run portfolio diagnostics: health check, concentration review, sector allocation, and stress test."},"headers":[],"relativePath":"import-portfolio.md","filePath":"import-portfolio.md","lastUpdated":1785677379000}'),m={name:"import-portfolio.md"},T=Object.assign(m,{setup(l){return(s,e)=>{const c=i("TickerForgeComplianceDisclaimer"),h=i("TickerForgeTrustBlock");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"import-a-portfolio-for-instant-diagnostics",tabindex:"-1"},[o("Import a Portfolio for Instant Diagnostics "),t("a",{class:"header-anchor",href:"#import-a-portfolio-for-instant-diagnostics","aria-label":'Permalink to "Import a Portfolio for Instant Diagnostics"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Enter your stock holdings and free cash to see how TickerForge reads the portfolio as a system. The analyzer resolves either a ticker or a company name, applies the latest available daily market price, and builds an in-memory portfolio for analysis. It does not place trades, connect to a broker, or save a public balance.",-1)),e[2]||(e[2]=t("p",null,[o("After you select "),t("strong",null,"Analyze Portfolio"),o(", TickerForge returns a Portfolio Snapshot, Health Check, Sector Allocation view, and Stress Test report. The output highlights concentration, sector exposure, cash buffer, stress-test impact, and the top risk factors worth reviewing.")],-1)),e[3]||(e[3]=t("p",null,"After the diagnostics are ready, you can leave an email and receive a consolidated PDF with those sections for your portfolio.",-1)),a(c),a(h,{kind:"portfolio"}),e[4]||(e[4]=t("h2",{id:"run-a-free-portfolio-health-check",tabindex:"-1"},[o("Run a Free Portfolio Health Check "),t("a",{class:"header-anchor",href:"#run-a-free-portfolio-health-check","aria-label":'Permalink to "Run a Free Portfolio Health Check"'},"​")],-1)),e[5]||(e[5]=t("p",null,"This is the action page for the portfolio diagnostics cluster. Add your holdings and cash below to run a free Portfolio Health Check, Portfolio Snapshot, Sector Allocation view, and Stress Test. The output is a risk review and decision-support report that shows what TickerForge found after reading your holdings, not a guarantee that future drawdowns can be avoided.",-1)),e[6]||(e[6]=t("p",null,[o("Use "),t("a",{href:"/workspace/"},"Workspace Login"),o(" when you want to return to saved diagnostics, email-linked reports, alert settings, and portfolio workflows after the first analysis. The import page is the fastest starting point; the workspace is where follow-up work continues.")],-1)),e[7]||(e[7]=t("p",null,[o("Not ready to enter your own holdings yet? Open the "),t("a",{href:"/portfolio-diagnostics"},"Portfolio Diagnostics demo"),o(" to inspect public model portfolios first.")],-1)),a(p,{"api-base":"https://api.ticker-forge.com"}),a(f),e[8]||(e[8]=d('<h2 id="manual-entry" tabindex="-1">Manual Entry <a class="header-anchor" href="#manual-entry" aria-label="Permalink to &quot;Manual Entry&quot;">​</a></h2><p>This first version supports long stock positions and USD cash. Add a holding by entering a ticker such as <code>MSFT</code> or a company name such as <code>Microsoft</code>, set the number of shares, and select <strong>Add</strong>. You can remove individual positions or reset the full input before analysis.</p><p>CSV and broker-screenshot import remain part of the broader TickerForge workflow, but this page keeps the web UI focused on manual entry so the first diagnostic experience stays clear.</p><h2 id="how-tickerforge-uses-the-data" tabindex="-1">How TickerForge Uses the Data <a class="header-anchor" href="#how-tickerforge-uses-the-data" aria-label="Permalink to &quot;How TickerForge Uses the Data&quot;">​</a></h2><p>The web analyzer keeps the editable holding list in your browser. When you select <strong>Analyze Portfolio</strong>, it sends only the ticker quantities and cash required to calculate the reports. The backend resolves current company data, sector, beta, business scores, and risk attributes, then returns the four diagnostic payloads directly to the page.</p><p>For the calculation logic, see the <a href="/methodology/portfolio-health-check">Portfolio Health Check methodology</a> and <a href="/methodology/portfolio-stress-test">Portfolio Stress Test methodology</a>. You can also explore the rules-based <a href="/portfolio-builder">Portfolio Builder</a>, review the full <a href="/portfolio-analysis">portfolio analysis toolkit</a>, or compare access on the <a href="/pricing">pricing page</a>.</p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/portfolio-diagnostics">Try model portfolio diagnostics</a> — inspect public examples before analyzing your own holdings.</li><li><a href="/portfolio-analysis">Portfolio Analysis reports</a> — learn what each diagnostic report measures and how to use it.</li><li><a href="/methodology/portfolio-health-check">Portfolio Health Check methodology</a> — understand the quality, concentration, and exposure checks.</li><li><a href="/methodology/portfolio-stress-test">Portfolio Stress Test methodology</a> — review the beta-weighted scenario calculations.</li><li><a href="/blog/how-to-stress-test-your-portfolio">How to stress test your portfolio</a> — use scenarios to review drawdown and concentration risk.</li><li><a href="/blog/portfolio-beta-calculator">Portfolio beta calculator</a> — learn how market sensitivity is estimated before interpreting the report.</li></ul><p>Portfolio Diagnostics are educational decision-support tools, not personalized investment advice.</p>',9))])}}});export{w as __pageData,T as default};
